-- Schema snapshot of GSP_database.duckdb; no records.
CREATE SEQUENCE progress_tracker_record_ids INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 115 NO CYCLE;;
CREATE TABLE colony_pcr_data(colony_pcr_id INTEGER, plate_id INTEGER, "Row" VARCHAR, C1 VARCHAR, C2 VARCHAR, C3 VARCHAR, C4 VARCHAR, C5 VARCHAR, C6 VARCHAR, C7 VARCHAR, C8 VARCHAR, C9 VARCHAR, C10 VARCHAR, C11 VARCHAR, C12 VARCHAR);;
CREATE TABLE colony_pcr_index("name" VARCHAR, id INTEGER PRIMARY KEY);;
CREATE TABLE colony_pcr_positives(colony_pcr_id INTEGER, plate_id INTEGER, well VARCHAR);;
CREATE TABLE colony_pcr_samples(colony_pcr_id INTEGER, plate_id INTEGER, JobID VARCHAR, BBID VARCHAR, Vector VARCHAR, Resistance VARCHAR, Primers VARCHAR, Length VARCHAR);;
CREATE TABLE customer_info(customer_id VARCHAR PRIMARY KEY, customer_name VARCHAR NOT NULL, customer_affiliation VARCHAR NOT NULL, sales_order INTEGER NOT NULL UNIQUE, customer_email VARCHAR NOT NULL UNIQUE, CHECK(regexp_full_match(customer_id, '[A-Z]{2,5}')), CHECK(regexp_full_match(customer_affiliation, '(University|Company) [A-Z]{3}')), CHECK((sales_order BETWEEN 10000000 AND 29999999)), UNIQUE(customer_name, customer_affiliation));;
CREATE TABLE dna_extraction_antibiotic(dna_extraction_id INTEGER, plate_id INTEGER, well_id VARCHAR, "value" VARCHAR);;
CREATE TABLE dna_extraction_bacteria(dna_extraction_id INTEGER, plate_id INTEGER, well_id VARCHAR, "value" VARCHAR);;
CREATE TABLE dna_extraction_data(dna_extraction_id INTEGER, plate_id INTEGER, "Row" VARCHAR, C1 VARCHAR, C2 VARCHAR, C3 VARCHAR, C4 VARCHAR, C5 VARCHAR, C6 VARCHAR, C7 VARCHAR, C8 VARCHAR, C9 VARCHAR, C10 VARCHAR, C11 VARCHAR, C12 VARCHAR);;
CREATE TABLE dna_extraction_incubation(dna_extraction_id INTEGER, plate_id INTEGER, well_id VARCHAR, "value" VARCHAR);;
CREATE TABLE dna_extraction_index("name" VARCHAR, id INTEGER PRIMARY KEY);;
CREATE TABLE dna_extraction_prep(dna_extraction_id INTEGER, plate_id INTEGER, well_id VARCHAR, "value" VARCHAR);;
CREATE TABLE dna_extraction_temperature(dna_extraction_id INTEGER, plate_id INTEGER, well_id VARCHAR, "value" VARCHAR);;
CREATE TABLE dna_quantification_extraction_plate(quantification_id INTEGER, JobID VARCHAR, BBID VARCHAR);;
CREATE TABLE dna_quantification_fragments(quantification_id INTEGER, JobID VARCHAR, BBID VARCHAR);;
CREATE TABLE dna_quantification_index("name" VARCHAR, id INTEGER PRIMARY KEY, "source" VARCHAR, source_details VARCHAR);;
CREATE TABLE dna_quantification_nanodrop(quantification_id INTEGER, row_number INTEGER, concentration_ng_ul FLOAT, a260_a280 FLOAT, a260_a230 FLOAT, a260 FLOAT, a280 FLOAT);;
CREATE TABLE dna_quantification_other(quantification_id INTEGER, JobID VARCHAR, BBID VARCHAR);;
CREATE TABLE job_log(work_no VARCHAR, bbi_id VARCHAR, order_date VARCHAR, so VARCHAR, gene_name VARCHAR, vector VARCHAR, cloning_site VARCHAR, resistance VARCHAR, length_bp INTEGER, quantity VARCHAR, prep VARCHAR, stage VARCHAR, insert_sequence VARCHAR, final_vector_sequence VARCHAR, plasmid_no VARCHAR, tube_id VARCHAR, host VARCHAR, temperature VARCHAR, competent_cells VARCHAR, notes VARCHAR);;
CREATE TABLE ligation_data(ligation_id INTEGER, "Well " VARCHAR, "Name" VARCHAR, BBID VARCHAR, "Vector " VARCHAR, Enzyme VARCHAR, "Vector Lot" VARCHAR, "Vector Position" VARCHAR, "Vol of Vector" VARCHAR, "Insert 1" VARCHAR, "Well position" VARCHAR, "Vol of Insert" VARCHAR, "Insert 2" VARCHAR, "Insert 3" VARCHAR, "H2O Volume" VARCHAR, "2XHF" VARCHAR, Len VARCHAR, Resistance VARCHAR, worksheet1 VARCHAR, worksheet2 VARCHAR);;
CREATE TABLE ligation_index("name" VARCHAR, id INTEGER PRIMARY KEY);;
CREATE TABLE sequencing_layout_data(sequencing_layout_id INTEGER, row_number INTEGER, well VARCHAR, wo VARCHAR, dna VARCHAR, primer VARCHAR, file_name VARCHAR);;
CREATE TABLE sequencing_layout_index("name" VARCHAR, id INTEGER PRIMARY KEY, "source" VARCHAR);;
CREATE TABLE sequencing_layout_plate(sequencing_layout_id INTEGER, row_letter VARCHAR, col INTEGER, field VARCHAR, "value" VARCHAR);;
CREATE TABLE sequencing_order_data(sequencing_order_id INTEGER, row_number INTEGER, well_pos VARCHAR, sample_type VARCHAR, seq_sample_id VARCHAR, seq_primer_id VARCHAR, file_name_request VARCHAR, conc_est VARCHAR, "comment" VARCHAR, dna_position VARCHAR, layout_wo VARCHAR, new_primer_id VARCHAR, new_file_name VARCHAR);;
CREATE TABLE sequencing_order_index("name" VARCHAR, id INTEGER PRIMARY KEY, "source" VARCHAR, plate_name VARCHAR);;
CREATE TABLE sequencing_validation_dilution(sequencing_validation_id INTEGER, row_number INTEGER, jobid VARCHAR, bbid VARCHAR, plasmid_id VARCHAR, seq_rx VARCHAR, seq_plate_well VARCHAR, conc VARCHAR, dil_fact VARCHAR, vol_to_prepare VARCHAR, water_vol VARCHAR, dna_vol VARCHAR);;
CREATE TABLE sequencing_validation_index("name" VARCHAR, id INTEGER PRIMARY KEY, "source" VARCHAR);;
CREATE TABLE sequencing_validation_pending(sequencing_validation_id INTEGER, row_number INTEGER, jobid VARCHAR, bbid VARCHAR, plasmid_id VARCHAR, notes VARCHAR, ng_ul VARCHAR, a260_280 VARCHAR, a260_230 VARCHAR, seq_rx VARCHAR, seq_plate_well VARCHAR);;
CREATE TABLE seq_log_data(seq_log_id INTEGER, row_number INTEGER, folder_name VARCHAR, job_id VARCHAR, vector_id VARCHAR, sg_ss_ok VARCHAR, sg_ds_ok VARCHAR, sg_mutation_or_fail VARCHAR, sg_primer_to_repeat VARCHAR, requirement VARCHAR, qc_file_name VARCHAR, work_no VARCHAR, bbi_id VARCHAR, gene_name VARCHAR, vector VARCHAR, length_bp VARCHAR, plasmid_no VARCHAR, cloning_site VARCHAR, resistance VARCHAR, growth_condition_temperature VARCHAR, order_date VARCHAR, delivery_date VARCHAR, "storage" VARCHAR, host VARCHAR, plasmid_qty VARCHAR, competent_cells VARCHAR, od260 VARCHAR, od280 VARCHAR, od260_280 VARCHAR, ng_ul VARCHAR);;
CREATE TABLE seq_log_index("name" VARCHAR, id INTEGER PRIMARY KEY, log_date VARCHAR, "version" VARCHAR, "source" VARCHAR);;
CREATE TABLE vector_log(vector VARCHAR PRIMARY KEY, resistance VARCHAR DEFAULT('') NOT NULL, "sequence" VARCHAR DEFAULT('') NOT NULL, source_url VARCHAR DEFAULT(''), verification_status VARCHAR DEFAULT(''));;
CREATE TABLE orders(customer_id VARCHAR, order_number INTEGER, genes_ordered INTEGER NOT NULL, status VARCHAR DEFAULT('In Progress') NOT NULL, FOREIGN KEY (customer_id) REFERENCES customer_info(customer_id), CHECK((order_number BETWEEN 1 AND 9999)), CHECK((genes_ordered >= 1)), CHECK((status IN ('Cancelled', 'In Progress', 'Completed', 'Completed (Partial)'))), PRIMARY KEY(customer_id, order_number));;
CREATE TABLE progress_tracker(customer_id VARCHAR NOT NULL, order_number INTEGER NOT NULL, item_number INTEGER NOT NULL, bbi_id VARCHAR GENERATED ALWAYS AS((((customer_id || lpad(CAST(order_number AS VARCHAR), 4, '0')) || '-') || lpad(CAST(item_number AS VARCHAR), 2, '0'))), work_number VARCHAR NOT NULL UNIQUE, status VARCHAR DEFAULT('0. Onboarding') NOT NULL, order_date DATE NOT NULL, gene_name VARCHAR NOT NULL, vector VARCHAR NOT NULL, cloning_site VARCHAR NOT NULL, resistance VARCHAR NOT NULL, length INTEGER NOT NULL, quantity VARCHAR NOT NULL, delivery_format VARCHAR NOT NULL, insert_sequence VARCHAR, final_vector_sequence VARCHAR, plasmid_number VARCHAR, tube_id VARCHAR, host VARCHAR, temperature VARCHAR, competent_cells VARCHAR, record_id BIGINT DEFAULT(nextval('progress_tracker_record_ids')) PRIMARY KEY, notes VARCHAR, CHECK((item_number BETWEEN 1 AND 99)), FOREIGN KEY (customer_id, order_number) REFERENCES orders(customer_id, order_number));;
CREATE TABLE oligo_log(date_code VARCHAR, work_number VARCHAR, "sequence" VARCHAR, purity VARCHAR, yield VARCHAR, CHECK((regexp_full_match(date_code, '[A-Z][0-9]{4}') AND (try_strptime((CAST(((2026 + ascii(substr(date_code, 1, 1))) - ascii('A')) AS VARCHAR) || substr(date_code, 2)), '%Y%m%d') IS NOT NULL))), FOREIGN KEY (work_number) REFERENCES progress_tracker(work_number), CHECK(("sequence" IS NULL)), CHECK((purity IN ('Pass', 'Fail'))), CHECK((yield IN ('Pass', 'Fail'))), PRIMARY KEY(date_code, work_number));;
CREATE TABLE primer_log(date_code VARCHAR, work_number VARCHAR, colony_pcr_primers VARCHAR[] DEFAULT(main.list_value()) NOT NULL, amplification_primers VARCHAR[] DEFAULT(main.list_value()) NOT NULL, sequencing_primers VARCHAR[] DEFAULT(main.list_value()) NOT NULL, CHECK((regexp_full_match(date_code, '[A-Z][0-9]{4}') AND (try_strptime((CAST(((2026 + ascii(substr(date_code, 1, 1))) - ascii('A')) AS VARCHAR) || substr(date_code, 2)), '%Y%m%d') IS NOT NULL))), FOREIGN KEY (work_number) REFERENCES progress_tracker(work_number), PRIMARY KEY(date_code, work_number));;
CREATE MACRO spine_of (k) AS (CASE  WHEN ((k IS NULL)) THEN (NULL) WHEN (EXISTS(SELECT 1 FROM job_log AS g WHERE (g.work_no = k))) THEN (k) WHEN (EXISTS(SELECT 1 FROM job_log AS g WHERE (g.work_no = "left"(k, (length(k) - 1))))) THEN ("left"(k, (length(k) - 1))) ELSE NULL END);;
CREATE VIEW job_log_rows AS SELECT rowid AS jt_rowid, * FROM job_log;;

